import { ref, shallowRef, watch, type Ref } from 'vue'

export function useCustomer(id: Ref<string>) {
  const customer = shallowRef<Customer | null>(null)
  const error = ref<string | null>(null)
  const loading = ref(false)

  watch(id, async (nextId, _prev, onCleanup) => {
    const controller = new AbortController()
    onCleanup(() => controller.abort())
    loading.value = true
    error.value = null
    try {
      const response = await fetch(`/api/customers/${encodeURIComponent(nextId)}`, {
        signal: controller.signal,
      })
      if (!response.ok) throw new Error(`Request failed: ${response.status}`)
      customer.value = await response.json()
    } catch (cause) {
      if (controller.signal.aborted) return
      customer.value = null
      error.value = cause instanceof Error ? cause.message : 'Unknown error'
    } finally {
      if (!controller.signal.aborted) loading.value = false
    }
  }, { immediate: true })

  return { customer, error, loading }
}

import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'

export function useStatusFilter() {
  const route = useRoute()
  const router = useRouter()
  const status = computed(() => {
    const value = route.query.status
    return value === 'open' || value === 'closed' ? value : 'open'
  })

  function setStatus(next: 'open' | 'closed') {
    void router.replace({ query: { ...route.query, status: next } })
  }

  return { status, setStatus }
}

