import { computed, shallowRef, type Ref } from 'vue'

const rows = shallowRef(new Map<string, Row>())
let pending: Row[] = []
let frame = 0

export function pushRow(row: Row) {
  pending.push(row)
  if (frame) return
  frame = requestAnimationFrame(() => {
    const next = new Map(rows.value)
    for (const item of pending) next.set(item.id, item)
    pending = []
    frame = 0
    rows.value = next
  })
}

export function useRow(id: Ref<string>) {
  return computed(() => rows.value.get(id.value) ?? null)
}

