import { inject, type App, type InjectionKey } from 'vue'

interface ApiClient { get<T>(path: string): Promise<T> }
const apiKey: InjectionKey<ApiClient> = Symbol('api')

export function createApiPlugin(client: ApiClient) {
  return {
    install(app: App) {
      app.provide(apiKey, client)
    },
  }
}

export function useApi(): ApiClient {
  const client = inject(apiKey)
  if (!client) throw new Error('API plugin is not installed')
  return client
}

import { computed, ref } from 'vue'

export function useDirty(initial = '') {
  const original = ref(initial)
  const current = ref(initial)
  const dirty = computed(() => current.value !== original.value)

  function commit() {
    original.value = current.value
  }

  return { current, dirty, commit }
}
